import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/widgets.dart';

/// Dữ liệu ảnh WebP 3D Chatbox dự phòng trực tiếp trong Dart code.
/// Giúp hiển thị tức thì trên app đang chạy mà không phụ thuộc vào việc
/// asset bundle phải rebuild khi thêm file mới.
const String _kChatboxWebpBase64 =
    '';

final Uint8List kChatboxWebpBytes = base64Decode(_kChatboxWebpBase64);

/// Widget hiển thị icon Chatbox dự phòng bằng Image.memory.
class ChatboxFallbackImage extends StatelessWidget {
  const ChatboxFallbackImage({
    super.key,
    this.width,
    this.height,
    this.fit = BoxFit.contain,
  });

  final double? width;
  final double? height;
  final BoxFit fit;

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      kChatboxWebpBytes,
      width: width,
      height: height,
      fit: fit,
      filterQuality: FilterQuality.medium,
    );
  }
}
